import {nivel} from './level.mjs';
import {protocolFloors,scopeProtocolCatalog,scopedProtocolRows,sharedProtocol,protocolLevels,onProtocolFloor,protocolStateMatches} from './protocol-scope.mjs';
import {criticalAge,chileToday,isoDay,validDateRange} from './protocol-aging.mjs';
