const cache=new Map(),KEY='atlas-protocol-matrix-view-v1';let catalogRequest;
async function readJSON(file){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(file,{signal:controller.signal});if(!response.ok)throw Error('No se pudo cargar la matriz. Revisa la conexión o guarda su paquete offline.');return await response.json();}catch(error){if(error.name==='AbortError')throw Error('La carga está tardando. Reintenta con conexión o usa la copia offline.');if(error instanceof TypeError||error instanceof SyntaxError)throw Error('No se pudo leer el detalle de protocolos. Revisa la conexión o guarda la matriz para usarla offline.');throw error;}finally{clearTimeout(timer);}}
function loadCatalog(){return catalogRequest||=readJSON('protocols/catalog.json').then(catalog=>{if(catalog.schema!==1||!Array.isArray(catalog.types)||catalog.types.length!==catalog.totalTypes||catalog.types.some(type=>!Array.isArray(type.facets)))throw Error('Versión de catálogo no compatible.');return catalog;}).catch(error=>{catalogRequest=null;throw error;});}
function loadType(catalog,type){const key=catalog.source.sha256+':'+type.id;if(cache.has(key)){const value=cache.get(key);cache.delete(key);cache.set(key,value);return value;}const pending=readJSON('protocols/'+type.file).then(chunk=>decodeMatrixRows(chunk,catalog,type)).catch(error=>{if(cache.get(key)===pending)cache.delete(key);throw error;});cache.set(key,pending);if(cache.size>8)cache.delete(cache.keys().next().value);return pending;}
export async function renderProtocolCatalog(root,ctx,options={}){
 const esc=ctx.esc,number=n=>Number(n).toLocaleString('es-CL');root.innerHTML='<p role="status">Cargando catálogo de protocolos…</p>';
 let catalog;
 try{catalog=await loadCatalog();}catch(error){if(!root.isConnected)return;root.innerHTML=`<p role="alert">${esc(error.message)}</p><button id="retryProtocolCatalog">Reintentar</button>`;root.querySelector('#retryProtocolCatalog').onclick=()=>renderProtocolCatalog(root,ctx,options);return;}
 if(!root.isConnected)return;
 // «Ver en el plano» encuadra cada folio por sus ejes (grilla del DWG de cada piso, también el −1).
 const enPlano=!!ctx.verProtocolos;
 const floor=protocolFloors[nivel.id],key=KEY+':'+nivel.id,baseScope=scopeProtocolCatalog(catalog,nivel.id);let scope=scopeProtocolCatalog(catalog,nivel.id,'ABIERTO');
 let chosen=null,rows=[],page=0,serial=0,recordId=null,stored={};const defaults=()=>({state:root.querySelector('#matrixScopeState')?.value??'ABIERTO',level:'',receiver:'',query:'',dateField:'issued',dateFrom:'',dateTo:'',asOf:chileToday(),criticalOnly:false});const filters=defaults();
 try{const value=JSON.parse(localStorage.getItem(key)||'null');if(value?.sourceSha256===catalog.source.sha256)stored=value;}catch{}
 if(options.selection)stored={...options.selection,specialty:'',query:''};
 const date=value=>{const iso=matrixDate(value,catalog.source.date1904);return isoDay(iso)?iso.split('-').reverse().join('-'):!String(value??'').trim()?'Sin fecha documentada':'Fecha no válida en Excel';};
 root.innerHTML=`<section class="matrixIntro"><div><span class="section-label">MATRIZ DE CONTROL · REV1</span><h2>Seleccionar protocolo</h2><p>${number(baseScope.total)} registros del piso · ${number(baseScope.types.length)} códigos · corte ${esc(catalog.source.cutoff.split('-').reverse().join('-'))}</p><small class="matrixScope">${esc(floor.name)} · ${esc(floor.code)} · incluye referencias compartidas explícitas</small></div><a href="source/${esc(catalog.source.filename)}" download="${esc(catalog.source.originalName)}" class="sourceLink">Descargar Excel original</a></section><div class="matrixOverview">${matrixStates.map(state=>`<div><i style="background:${stateColors[state]}"></i><span>${stateLabels[state]}</span><b>${number(baseScope.states[state]||0)}</b></div>`).join('')}</div>${Object.keys(catalog.audit.differences).length?'<p class="matrixReconcile">Totales del piso por filas del registro. La comprobación del Excel completo está disponible en la fuente. <button id="matrixAuditOpen">Ver comprobación</button></p>':''}<div class="matrixFloorState"><div class="actions"><button type="button" data-quick-state="ABIERTO">Abiertos</button><button type="button" data-quick-state="CLOSED_ALL">Cerrados</button><button type="button" data-quick-state="NULO">Nulos</button><button type="button" data-quick-state="">Todos</button><button type="button" data-quick-state="REVIEW">Revisar</button></div><label>Mostrar protocolos de ${esc(floor.code)}<select id="matrixScopeState"><option value="ABIERTO">Abiertos</option><option value="">Todos los estados de este piso</option><option value="CERRADO">Cerrados</option><option value="CERRADO POR AUTOCONTROL">Cerrados por autocontrol</option><option value="CLOSED_ALL">Cerrados (incluye autocontrol)</option><option value="PENDING_CLOSURE">Pendientes de cierre (abiertos)</option><option value="NULO">Nulos</option></select></label><p id="matrixFloorCount" role="status"></p><small>Los compartidos incluyen este piso en NIVEL. Las referencias compuestas se conservan tal como están escritas; no se deducen pisos intermedios. Los registros sin nivel no se asignan a un piso.</small></div><div class="matrixLayout"><section class="matrixPicker"><div class="matrixPickerControls"><label for="matrixSpecialty">Especialidad / actividad</label><select id="matrixSpecialty"><option value="">Todas las especialidades</option>${scope.specialties.map(group=>`<option value="${group.id}">${esc(group.name)} · ${number(group.count)}</option>`).join('')}</select><label for="matrixTypeSearch">Buscar protocolo</label><input id="matrixTypeSearch" type="search" placeholder="Pintura asepsia baja, planchas RH, código…" autocomplete="off"><label for="matrixType">Protocolo / proceso</label><select id="matrixType"><option value="">Selecciona un protocolo</option></select><p id="matrixTypeCount" role="status"></p></div><details class="matrixBrowse"><summary>Explorar protocolos por especialidad</summary><div id="matrixGroups"></div></details></section><section id="matrixRegisters" class="matrixRegisters" aria-label="Registros del protocolo"><div class="matrixPlaceholder"><h3>Elige un protocolo</h3><p>Despliega una especialidad o busca por nombre o código. Después podrás consultar sus folios, niveles, estados y responsables.</p></div></section></div><details class="matrixSource"><summary>Fuente original y comprobación global de la matriz</summary><p>${esc(catalog.source.originalName)} · ${esc(catalog.source.registrySheet)} · ${esc(catalog.source.revision)}</p><p>La consulta conserva los valores guardados en el archivo. Los estados de esta matriz no equivalen a la aprobación técnica de los registros locales de Atlas.</p><p>${catalog.audit.statusWhitespace.length} estados contienen espacios adicionales: se muestran como «Abierto». El recuento por filas da ${number(catalog.audit.calculatedStates.ABIERTO)} abiertos; el resumen del Excel muestra ${number(catalog.audit.declaredStates.ABIERTO)}. El original se conserva íntegro.</p><p>${catalog.audit.duplicateFolios.length} combinaciones de código y folio se repiten; se mantienen todas las filas. Las tablas dinámicas y hojas históricas ocultas no se suman de nuevo.</p><p>«RECINTOS» y «NIVEL» se muestran tal como figuran en el Excel; no se asignan automáticamente a las geometrías del visor.</p><small>SHA256 ${esc(catalog.source.sha256)}</small></details>`;
 const $=id=>root.querySelector('#'+id),save=()=>{try{localStorage.setItem(key,JSON.stringify({sourceSha256:catalog.source.sha256,specialty:$('matrixSpecialty').value,query:$('matrixTypeSearch').value,typeId:chosen?.id||'',filters,page,recordId}));}catch{}};
 if($('matrixAuditOpen'))$('matrixAuditOpen').onclick=()=>{root.querySelector('.matrixSource').open=true;root.querySelector('.matrixSource').scrollIntoView({block:'start'});};
 $('matrixSpecialty').value=scope.specialties.some(g=>g.id===stored.specialty)?stored.specialty:'';$('matrixTypeSearch').value=typeof stored.query==='string'?stored.query.slice(0,300):'';
 function types(){return selectTypes(scope,{specialty:$('matrixSpecialty').value,query:$('matrixTypeSearch').value});}
 function groups(){const available=types(),ids=new Set(available.map(type=>type.id));$('matrixType').innerHTML='<option value="">Selecciona un protocolo</option>'+available.map(type=>`<option value="${type.id}">${esc(type.code+' · '+type.name)}</option>`).join('');$('matrixType').value=chosen&&ids.has(chosen.id)?chosen.id:'';$('matrixTypeCount').textContent=number(available.length)+(available.length===1?' protocolo disponible':' protocolos disponibles');$('matrixGroups').innerHTML=scope.specialties.filter(group=>(!$('matrixSpecialty').value||group.id===$('matrixSpecialty').value)&&group.typeIds.some(id=>ids.has(id))).map(group=>{const matches=available.filter(type=>group.typeIds.includes(type.id));return `<details class="matrixGroup" ${$('matrixSpecialty').value||$('matrixTypeSearch').value||chosen&&group.typeIds.includes(chosen.id)?'open':''}><summary><span>${esc(group.name)}</span><small>${matches.length} protocolos</small></summary><div>${matches.map(type=>`<button class="matrixTypeChoice" data-matrix-type="${type.id}" aria-pressed="${chosen?.id===type.id}"><span>${esc(type.name)}</span><small>${esc(type.code)} · ${number(type.visibleCount)} registros</small></button>`).join('')}</div></details>`;}).join('')||'<p class="matrixNoResults">Sin protocolos coincidentes. Prueba otro nombre o código.</p>';root.querySelectorAll('[data-matrix-type]').forEach(button=>button.onclick=()=>choose(button.dataset.matrixType));}
 async function choose(id,restore=false){const type=types().find(type=>type.id===id);const request=++serial;chosen=type||null;rows=[];recordId=null;page=0;if(!restore)Object.assign(filters,defaults());groups();save();if(!type){$('matrixRegisters').innerHTML='<div class="matrixPlaceholder"><h3>Elige un protocolo</h3><p>Selecciona un proceso para consultar sus registros.</p></div>';return;}$('matrixRegisters').innerHTML=`<p role="status">Cargando ${esc(type.name)}…</p>`;try{const loaded=await loadType(catalog,type);if(request!==serial||!root.isConnected)return;rows=scopedProtocolRows(loaded,nivel.id);if(restore){for(const key of ['level','receiver','query','dateField','dateFrom','dateTo','asOf'])if(typeof stored.filters?.[key]==='string')filters[key]=stored.filters[key].slice(0,500);filters.criticalOnly=stored.filters?.criticalOnly===true;page=Number.isInteger(stored.page)?stored.page:0;recordId=typeof stored.recordId==='string'?stored.recordId:null;}if(options.selection&&recordId){const matches=selectMatrixRows(rows,filters,catalog.source.date1904),index=matches.findIndex(record=>record.id===recordId);if(index>=0)page=Math.floor(index/25);}registerShell();save();if(innerWidth<700)$('matrixRegisters').scrollIntoView({block:'start'});}catch(error){if(request!==serial||!root.isConnected)return;$('matrixRegisters').innerHTML=`<h3>${esc(type.name)}</h3><p role="alert">${esc(error.message)}</p><button id="retryMatrixType">Reintentar detalle</button>`;$('retryMatrixType').onclick=()=>choose(type.id,restore);}}
 const optionList=(field,empty)=>matrixFacets(rows,field).map(([value,n])=>`<option value="${esc(value||'~')}">${esc(field==='state'?stateLabels[value]||value||empty:value||empty)} · ${number(n)}</option>`).join('');
 function registerShell(){const fieldLabels=catalog.source.columns; $('matrixRegisters').innerHTML=`<div class="matrixTypeHeading"><span class="section-label">${esc(chosen.code)}</span><h3>${esc(chosen.name)}</h3><p>${number(rows.length)} registros de ${esc(floor.code)} en la matriz${chosen.names.length>1?' · '+chosen.names.length+' variantes de nombre en origen':''}</p><button id="changeMatrixType">Cambiar protocolo</button>${enPlano?'<button id="matrixOnPlan" class="primary">Ver en el plano</button>':''}</div><div class="matrixRecordFilters"><label>Estado<select id="matrixState"><option value="">Todos los estados</option>${matrixStates.map(state=>`<option value="${state}">${stateLabels[state]} · ${number(rows.filter(row=>row.state?.trim()===state).length)}</option>`).join('')}<option value="CLOSED_ALL">Cerrados (incluye autocontrol) · ${number(rows.filter(row=>['CERRADO','CERRADO POR AUTOCONTROL'].includes(row.state?.trim())).length)}</option><option value="PENDING_CLOSURE">Pendiente de cierre (abiertos) · ${number(rows.filter(row=>row.state?.trim()==='ABIERTO').length)}</option></select></label><label>Nivel del Excel<select id="matrixLevel"><option value="">Todas las referencias de ${esc(floor.code)}</option>${optionList('level','Sin nivel documentado')}</select></label><label>Recibe<select id="matrixReceiver"><option value="">Todas las personas</option>${optionList('receiver','Sin receptor documentado')}</select></label><label class="matrixRecordSearch">Buscar en los registros<input id="matrixRecordSearch" type="search" placeholder="Folio, elemento, ejes o persona…"></label></div><details class="matrixDates" ${filters.dateFrom||filters.dateTo?'open':''}><summary>Filtrar por fechas</summary><div><label>Fecha a consultar<select id="matrixDateField"><option value="issued">Elaboración</option><option value="closedDate">Cierre</option></select></label><label>Desde<input id="matrixDateFrom" type="date"></label><label>Hasta<input id="matrixDateTo" type="date"></label></div></details><div class="matrixAgingFilter"><label class="check"><input id="matrixCriticalOnly" type="checkbox" ${filters.criticalOnly?'checked':''}> Solo críticos: más de 1 año abiertos</label><label>Evaluar antigüedad al<input id="matrixAsOf" type="date"></label><small>Pendiente de cierre equivale a Abierto. Las fechas ausentes no se estiman.</small></div><p id="matrixDateError" role="alert" hidden></p><div class="matrixResultHead"><strong id="matrixResultCount" role="status"></strong><button id="clearMatrixFilters">Limpiar filtros</button></div><div class="matrixTableWrap"><table class="matrixTable"><thead><tr><th>Folio</th><th>Nivel</th><th class="matrixWide">Elemento / ejes</th><th id="matrixDateColumn">Elaboración</th><th>Estado</th><th class="matrixWide">Recibe</th></tr></thead><tbody id="matrixRows"></tbody></table></div><div class="matrixPagination"><button id="matrixPrevious">Anterior</button><span id="matrixPage"></span><button id="matrixNext">Siguiente</button></div>`;
  $('changeMatrixType').onclick=()=>{$('matrixType').scrollIntoView({block:'nearest'});$('matrixType').focus({preventScroll:true});};if($('matrixOnPlan'))$('matrixOnPlan').onclick=()=>ctx.verProtocolos({tipo:chosen,filas:rows});for(const [id,key] of [['matrixState','state'],['matrixLevel','level'],['matrixReceiver','receiver']]){if(![...$(id).options].some(option=>option.value===filters[key]))filters[key]='';$(id).value=filters[key];$(id).onchange=event=>{filters[key]=event.target.value;page=0;recordId=null;if(key==='state'){setScopeState(filters.state);return;}renderRows();};}for(const [id,key] of [['matrixDateField','dateField'],['matrixDateFrom','dateFrom'],['matrixDateTo','dateTo'],['matrixAsOf','asOf']]){$(id).value=filters[key];$(id).onchange=event=>{filters[key]=event.target.value;page=0;recordId=null;renderRows();};}$('matrixCriticalOnly').onchange=event=>{filters.criticalOnly=event.target.checked;page=0;recordId=null;renderRows();};$('matrixRecordSearch').value=filters.query;$('matrixRecordSearch').oninput=event=>{filters.query=event.target.value;page=0;recordId=null;renderRows();};$('clearMatrixFilters').onclick=()=>{Object.assign(filters,defaults());page=0;recordId=null;registerShell();};$('matrixPrevious').onclick=()=>{page--;recordId=null;renderRows();};$('matrixNext').onclick=()=>{page++;recordId=null;renderRows();};renderRows();
 }
 function renderRows(){const matches=selectMatrixRows(rows,filters,catalog.source.date1904),current=matrixPage(matches,page);page=current.page;$('matrixDateColumn').textContent=filters.dateField==='closedDate'?'Cierre':'Elaboración';const valid=validDateRange(filters.dateFrom,filters.dateTo)&&!!isoDay(filters.asOf);$('matrixDateError').hidden=valid;$('matrixDateError').textContent=!isoDay(filters.asOf)?'Selecciona una fecha válida para evaluar la antigüedad.':'La fecha inicial debe ser anterior o igual a la fecha final.';$('matrixResultCount').textContent=number(matches.length)+' de '+number(rows.length)+' registros';$('matrixRows').innerHTML=current.rows.map(record=>`<tr data-matrix-id="${esc(record.id)}" class="${recordId===record.id?'selected':''}"><td><button data-matrix-row="${esc(record.id)}" aria-expanded="${recordId===record.id}">${esc(record.folio||'Sin folio')}</button><small>Fila ${record.sourceRow}</small></td><td>${esc(record.level||'Sin nivel')}${sharedProtocol(record.level)?'<small>Compartido</small>':''}</td><td class="matrixWide">${esc(record.element||'Sin elemento')}<small>${esc(record.axes||'Sin ejes')}</small></td><td>${esc(date(record[filters.dateField==='closedDate'?'closedDate':'issued']))}${criticalAge(record,filters.asOf,catalog.source.date1904).critical?'<small class="criticalBadge">Crítico · más de 1 año</small>':''}</td><td><span class="matrixState" style="--state-color:${stateColors[record.state?.trim()]||'#8a929b'}">${esc(stateLabels[record.state?.trim()]||record.state||'Sin estado')}</span></td><td class="matrixWide">${esc(record.receiver||'Sin receptor')}</td></tr>`).join('')||'<tr><td colspan="6">Sin registros coincidentes.</td></tr>';$('matrixPage').textContent='Página '+(page+1)+' de '+current.pages;$('matrixPrevious').disabled=page===0;$('matrixNext').disabled=page+1>=current.pages;root.querySelectorAll('[data-matrix-row]').forEach(button=>button.onclick=()=>{const id=button.dataset.matrixRow;recordId=recordId===id?null:id;renderRows();[...root.querySelectorAll('[data-matrix-row]')].find(node=>node.dataset.matrixRow===id)?.focus({preventScroll:true});});const record=current.rows.find(row=>row.id===recordId);if(record){const duplicate=catalog.audit.duplicateFolios.find(group=>group.code===chosen.code&&group.rows.includes(record.sourceRow));const detail=`<h4>${esc(chosen.code)} · Folio ${esc(record.folio||'Sin folio')}</h4><dl>${Object.entries(catalog.source.columns).map(([field,name])=>`<div><dt>${esc(name)}</dt><dd>${esc(['issued','closedDate'].includes(field)?date(record[field]):record[field]??'Sin dato documentado')}</dd></div>`).join('')}</dl><p class="matrixRecordSource">${esc(catalog.source.registrySheet)} · fila ${record.sourceRow}. Valores originales guardados; consulta de solo lectura.</p>${duplicate?`<p>Este código y folio también aparece en las filas ${duplicate.rows.join(', ')}. Las filas se conservan por separado.</p>`:''}${enPlano?`<p><button id="matrixRecordOnPlan" class="primary">Ver protocolo ${esc(numeroProtocolo(record.folio))} en el plano</button></p>`:''}`;root.querySelector('[data-matrix-id="'+record.id+'"]').insertAdjacentHTML('afterend','<tr class="matrixExpandedRow"><td colspan="6"><section id="matrixRecordDetail" class="matrixRecordDetail" aria-label="Ficha del protocolo">'+detail+'</section></td></tr>');$('matrixRecordOnPlan')?.addEventListener('click',()=>ctx.verProtocolos({tipo:chosen,filas:rows,foco:record.id}));}save();}
 function updateScopeCount(){ $('matrixFloorCount').textContent=number(scope.matching)+' registros · '+number(scope.types.length)+' protocolos · '+number(scope.shared)+' registros compartidos'; }
 function setScopeState(state){
  $('matrixScopeState').value=state;filters.state=state;scope=scopeProtocolCatalog(catalog,nivel.id,state);const specialty=$('matrixSpecialty').value;
  $('matrixSpecialty').innerHTML='<option value="">Todas las especialidades</option>'+scope.specialties.map(group=>`<option value="${group.id}">${esc(group.name)} · ${number(group.count)}</option>`).join('');
  $('matrixSpecialty').value=scope.specialties.some(group=>group.id===specialty)?specialty:'';updateScopeCount();groups();
  if(chosen&&!types().some(type=>type.id===chosen.id)){choose('');return;}
  if(chosen&&$('matrixState')){page=0;recordId=null;$('matrixState').value=state;renderRows();}save();
 }
 async function quickList(state){
  const request=++serial;chosen=null;groups();const target=$('matrixRegisters');target.innerHTML='<p role="status">Cargando lista del piso…</p>';
  try{const result=[];const candidates=state==='REVIEW'?catalog.types:scopeProtocolCatalog(catalog,nivel.id,state).types;
   for(let i=0;i<candidates.length;i+=6){const batch=candidates.slice(i,i+6);const chunks=await Promise.all(batch.map(type=>loadType(catalog,type)));if(request!==serial||!root.isConnected)return;chunks.forEach((chunk,index)=>{for(const row of chunk){const levels=protocolLevels(row.level),anomaly=levels.length!==1;if(state==='REVIEW'?(anomaly&&(levels.length===0||onProtocolFloor(row.level,nivel.id))):(!anomaly&&onProtocolFloor(row.level,nivel.id)&&protocolStateMatches(row.state,state)))result.push({row,type:batch[index]});}});}
   let current=0;const draw=()=>{const pages=Math.max(1,Math.ceil(result.length/25));target.innerHTML='<h3>'+esc(state==='REVIEW'?'Revisar · compartidos o sin nivel claro':state==='CLOSED_ALL'?'Cerrados':state==='ABIERTO'?'Abiertos':state==='NULO'?'Nulos':'Todos')+' · '+esc(floor.name)+'</h3><p>'+number(result.length)+' registros</p><div class="matrixQuickRows">'+result.slice(current*25,current*25+25).map(({row,type},i)=>'<details><summary>'+esc(type.code+' · '+(row.folio||'Sin folio')+' · '+(stateLabels[row.state?.trim()]||row.state))+'</summary><p>'+esc(type.name)+'</p><p>Nivel: '+esc(row.level||'Sin nivel')+' · '+esc(row.element||'Sin elemento')+'</p><p>'+esc(row.receiver||'Sin receptor')+' · '+esc(date(row.issued))+'</p><button data-quick-detail="'+i+'">Profundizar en este protocolo</button></details>').join('')+'</div><div class="matrixPagination"><button id="quickPrev" '+(current?'':'disabled')+'>Anterior</button><span>Página '+(current+1)+' de '+pages+'</span><button id="quickNext" '+(current+1<pages?'':'disabled')+'>Siguiente</button></div>';target.querySelector('#quickPrev').onclick=()=>{current--;draw();};target.querySelector('#quickNext').onclick=()=>{current++;draw();};target.querySelectorAll('[data-quick-detail]').forEach(b=>b.onclick=()=>{const item=result[current*25+Number(b.dataset.quickDetail)];setScopeState('');choose(item.type.id);});};draw();target.scrollIntoView({block:'start'});
  }catch(error){if(request===serial&&root.isConnected)target.textContent=error.message;}
 }
 root.querySelectorAll('[data-quick-state]').forEach(button=>button.onclick=()=>quickList(button.dataset.quickState));
 $('matrixScopeState').onchange=event=>{setScopeState(event.target.value);quickList(event.target.value);};updateScopeCount();
 function selectionChanged(){const allowed=types();if(chosen&&!allowed.some(type=>type.id===chosen.id))choose('');else{groups();save();}}
 $('matrixSpecialty').onchange=selectionChanged;$('matrixTypeSearch').oninput=selectionChanged;$('matrixType').onchange=event=>choose(event.target.value);groups();if(types().some(type=>type.id===stored.typeId))choose(stored.typeId,true);
}
export {loadCatalog as loadProtocolCatalog};
